<?php
namespace App\Http\Controllers\Platform;
use App\Http\Controllers\Controller; use App\Models\{Agency,Plan,User}; use App\Services\AccountingService; use Illuminate\Http\Request; use Illuminate\Support\Facades\{Cache,Hash}; use Illuminate\Support\Str;
class AgencyController extends Controller { public function index(){return view('platform.agencies',['agencies'=>Agency::with('plan')->latest()->paginate(30),'plans'=>Plan::all()]);} public function store(Request $r,AccountingService $acct){$d=$r->validate(['name'=>'required|max:180','email'=>'required|email|unique:users,email','phone'=>'nullable','license_number'=>'nullable','plan_id'=>'nullable|integer','owner_name'=>'required','password'=>'required|min:8']);$a=Agency::create(['name'=>$d['name'],'slug'=>Str::slug($d['name']).'-'.strtolower(Str::random(4)),'phone'=>$d['phone']??null,'license_number'=>$d['license_number']??null,'license_status'=>'unverified','plan_id'=>$d['plan_id']??null,'is_active'=>1,'trial_ends_at'=>now()->addDays(30)]);User::create(['agency_id'=>$a->id,'name'=>$d['owner_name'],'email'=>$d['email'],'password'=>Hash::make($d['password']),'role'=>'agency_owner','locale'=>'fa','is_active'=>1]);$acct->ensureDefaultAccounts($a);return back()->with('success', __('Rahnama created.'));} public function toggle(Agency $agency){$agency->update(['is_active'=>!$agency->is_active]);Cache::forget('rahnuma:marketplace:home:v8');return back();} }
